(() => {
'use strict';
const app=document.getElementById('lesson-app'), engine=window.Maths1to9LessonEngine, store=window.Maths1to9Progress, router=engine.createRouter();
const slug='adding-decimal-numbers', ids=['learn','try-it','practice','check'], labels=['Learn','Try it','Practice','Check'];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const questions=[['8.4','2.35','10.75'],['3.6','1.25','4.85'],['12.08','4.7','16.78'],['0.95','2.6','3.55'],['7.48','3.76','11.24'],['6.75','2.40','9.15'],['5.8','0.34','6.14'],['1.75','0.8','2.55']];
let state={stage:0, guided:0, practice:2, phase:0, answers:{}, learned:false, submitted:false}, queue=Promise.resolve();
const answer=i=>state.answers[i]||(state.answers[i]={offset:1,value:'',digits:[],phase:0});
const activities=()=>[{id:'learn',kind:'learn',completed:state.learned},...questions.map((q,i)=>({id:`q${i}`,kind:i<2?'guided':'answer',completed:answer(i).earned||answer(i).correct,correct:answer(i).earned||answer(i).correct,firstCorrect:answer(i).firstCorrect})),{id:'reason',kind:'answer',completed:state.reasonEarned||state.reasonCorrect,correct:state.reasonEarned||state.reasonCorrect,firstCorrect:state.reasonFirst}];
function save(){const score=engine.calculateScore(activities()); const snapshot=JSON.parse(JSON.stringify({title:'Adding decimal numbers',pathname:location.pathname,totalSections:4,currentSectionId:ids[state.stage],currentSectionIndex:state.stage,highestUnlockedIndex:3,finished:state.submitted&&state.reasonReviewed,score,decimalState:state,completionPercent:Math.round(activities().filter(a=>a.completed).length/10*100)}));queue=queue.catch(()=>{}).then(()=>store.saveLessonProgress(slug,snapshot));refreshScore();}
function refreshScore(){const s=engine.calculateScore(activities()),badge=app.querySelector('.rounding-score');if(badge){badge.setAttribute('aria-label',`${s.points} of ${s.maximumPoints} points earned`);badge.querySelector('span').textContent=s.points;badge.querySelector('.practice-progress-ring').style.setProperty('--practice-progress',`${s.points/s.maximumPoints*100}%`);}}
const cells=n=>{const [w,d='']=n.split('.');return [w.length>1?w[0]:'',w.slice(-1),'.',d[0]||'',d[1]||''];};
function row(n,offset=0,extra=''){return `<div class="decimal-row ${extra}" style="--offset:${offset}">${cells(n).map(c=>`<span>${c||'&nbsp;'}</span>`).join('')}</div>`;}
function grid(a,b,{offset=0,move=false,result='',carry=''}={}){return `<div class="decimal-grid"><div class="decimal-labels"><span>Tens</span><span>Ones</span><span>•</span><span>Tenths</span><span>Hundredths</span></div>${carry?`<div class="decimal-carry" aria-label="Carried digits">${carry.split('|').map(c=>`<span>${c}</span>`).join('')}</div>`:''}${row(a)}<div class="decimal-add"><b aria-hidden="true">+</b>${row(b,offset,move?'movable':'')}</div>${result?row(result,0,'decimal-total'):''}</div>`;}
const controls=i=>`<div class="decimal-moves" role="group" aria-label="Move the second number"><button type="button" class="button" data-move="${i},-1" aria-label="Move second number left">← Left</button><button type="button" class="button" data-move="${i},1" aria-label="Move second number right">Right →</button></div>`;
function learn(){return `<h2 class="lesson-section__title">Line up the decimal points</h2><p>Add <strong>14.7 + 6.82</strong>. Ones go under ones, tenths under tenths and hundredths under hundredths.</p>${grid('14.70','6.82',{result:'21.52',carry:'1|1||| '})}<p>We can write <strong>14.7 = 14.70</strong>. A zero at the end is optional: it does not change the value.</p><ol><li>Hundredths: 0 + 2 = 2.</li><li>Tenths: 7 + 8 = 15 tenths. Write 5 tenths and carry 1 one above the ones column.</li><li>Ones: 4 + 6 + the carried 1 = 11. Write 1 and carry 1 ten.</li><li>Tens: 1 + the carried 1 = 2.</li></ol><div class="rounding-note"><strong>Your method</strong><ol><li>Write the numbers underneath each other.</li><li><strong>Line up the decimal points.</strong></li><li>Add a zero at the end if it helps you see the columns.</li><li>Add from right to left, carrying when needed.</li><li>Put the answer’s decimal point directly below the others.</li></ol></div><p>Quick sense check: 14.7 is about 15 and 6.82 is about 7. An answer near 22 makes sense.</p>`;}
function guided(){const i=state.guided,a=answer(i),q=questions[i],p=a.phase;let body=`<p class="rounding-counter">Example ${i+1} of 2</p><h2 class="lesson-section__title">${q[0]} + ${q[1]}</h2>`;
body+=grid(p>=2?Number(q[0]).toFixed(2):q[0],q[1],{offset:a.offset,move:p===0,result:p>=3?(i===0?[a.digits[3]||' ',a.digits[2]||' ','.',a.digits[1]||' ',a.digits[0]||' '].join(''):`${a.digits[2]||' '}.${a.digits[1]||' '}${a.digits[0]||' '}`):'',carry:i===0&&a.digits[2]?'1||||':''});
if(p===0)body+=`<p>${i===0?'Move the second row until the decimal points line up.':'Set out this addition.'} Drag the row, use the arrow keys on it, or use the buttons.</p>${controls(i)}`;
else if(p===1)body+='<label for="guided-input">What could you write after the 4 to make the hundredths column easier to see?</label><input id="guided-input" class="final-check-input" inputmode="numeric" autocomplete="off">';
else if(p===2||p===3){const step=a.digits.length;body+=`<p>${p===2?'8.4 = 8.40. The optional zero keeps the value the same.':''}</p><label for="guided-input">Enter the ${['hundredths','tenths','ones','tens'][step]} digit in the answer.</label><input id="guided-input" class="final-check-input" inputmode="numeric" maxlength="1" autocomplete="off">`;}
else if(p===4)body+='<label for="guided-input">Why did you put the decimal point there?</label><select id="guided-input" class="final-check-input"><option value="">Choose a reason</option><option value="last">It goes before the last digit.</option><option value="aligned">It is directly below the aligned decimal points.</option><option value="middle">It goes in the middle of the answer.</option></select>';
else body+=`<p class="rounding-note">Correct: ${q[0]} + ${q[1]} = ${q[2]}. The decimal points stay in the same column.</p>`;
return body;}
function working(i){const a=answer(i),q=questions[i],locked=state.stage===3&&state.submitted;return `<div data-work="${i}">${grid(q[0],q[1],{offset:a.offset,move:!locked})}${!locked?controls(i):''}</div><label for="value-${i}">Your answer ${i===5?'(£)':i===7?'(litres)':''}</label><input class="final-check-input" id="value-${i}" data-answer="${i}" inputmode="decimal" value="${esc(a.value)}" ${locked?'disabled':''} autocomplete="off">`;}
function practice(){const i=state.practice;return `<p class="rounding-counter">Question ${i-1} of 4</p><h2 class="lesson-section__title">${i===5?'£6.75 + £2.40':questions[i].slice(0,2).join(' + ')}</h2><p>Show your column layout by positioning the second row, then enter your answer.</p>${working(i)}${answer(i).correct?`<p class="rounding-note">Correct: ${i===5?'£9.15':questions[i][2]}. Your decimal points line up.</p>`:''}`;}
function check(){return `<h2 class="lesson-section__title">Show what you know</h2><p>Complete all three questions, then use Continue to submit. Show each column layout by positioning its second row.</p><h3>1. Work out 5.8 + 0.34</h3>${working(6)}<h3>2. Explain the mistake</h3><p>A student says: “To add 5.8 and 0.34, I should line up the last digits.” Explain why this is wrong and what should line up instead.</p><label for="reason">Your explanation</label><textarea id="reason" ${state.submitted?'disabled':''}>${esc(state.reason)}</textarea><h3>3. Water in two bottles</h3><p>A bottle contains 1.75 litres. Another contains 0.8 litres. How much water is there altogether?</p>${working(7)}${state.submitted?review():''}`;}
function review(){return `<div class="rounding-note"><h3>Check your explanation</h3><p>The last digits have different place values: 8 is in the tenths column, while 4 is in the hundredths column. Line up the decimal points so digits with the same place value are added.</p><label><input type="checkbox" id="reason-review" ${state.reasonCorrect?'checked':''}> My explanation includes both the different place values and lining up the decimal points.</label><p>Explanation is self-assessed against this model.</p><p>Question 1: ${answer(6).correct?'Correct.':'Revisit '+(!answer(6).aligned?'alignment.':'addition and carrying.')} 5.80 + 0.34 = 6.14.</p><p>Question 3: ${answer(7).correct?'Correct.':'Revisit '+(!answer(7).aligned?'alignment.':'addition and carrying.')} 1.75 + 0.80 = 2.55 litres.</p><div id="result" role="status">${result()}</div></div>`;}
function result(){if(!state.reasonReviewed)return 'Compare your explanation, then press Continue for your result.';return `<h3>${answer(6).correct&&answer(7).correct&&state.reasonCorrect?'You’re ready':'Practise once more'}</h3><p>${!answer(6).aligned||!answer(7).aligned?'Revisit lining up the decimal points.':!answer(6).correct||!answer(7).correct?'Revisit adding from right to left and carrying.':!state.reasonCorrect?'Revisit why tenths and hundredths belong in different columns.':'You can align the numbers, add accurately and explain the alignment.'}</p><a href="#practice">Practise again</a> · <button type="button" class="button" id="retry-check">Retry Check</button>`;}
function mountMoves(){app.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const [i,d]=b.dataset.move.split(',').map(Number);move(i,d);});app.querySelectorAll('.movable').forEach(el=>{const i=state.stage===1?state.guided:Number(el.closest('[data-work]').dataset.work);el.tabIndex=0;el.setAttribute('role','slider');el.setAttribute('aria-label',`Position of ${questions[i][1]}; use left and right arrow keys`);el.setAttribute('aria-valuemin','-1');el.setAttribute('aria-valuemax','1');el.setAttribute('aria-valuenow',answer(i).offset);el.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();move(i,e.key==='ArrowLeft'?-1:1);app.querySelector(state.stage===1?'.movable':`[data-work="${i}"] .movable`)?.focus();}};let x;el.onpointerdown=e=>{x=e.clientX;el.setPointerCapture(e.pointerId);};el.onpointerup=e=>{const delta=e.clientX-x;if(Math.abs(delta)>15)move(i,Math.round(delta/(el.clientWidth/5)));};});}
function move(i,d){answer(i).offset=Math.max(-1,Math.min(1,answer(i).offset+d));answer(i).correct=false;save();render();}
function assess(i){const a=answer(i),raw=a.value.trim().replace(/^£\s*/,'');a.aligned=a.offset===0;const numeric=/^\d+(\.\d+)?$/.test(raw)&&Number(raw)===Number(questions[i][2]);a.correct=a.aligned&&numeric;a.earned=a.earned||a.correct;if(a.firstCorrect===undefined)a.firstCorrect=a.correct;return a.correct;}
function feedback(text){app.querySelector('#feedback').textContent=text;}
function next(){if(state.stage===0){state.learned=true;show(1);return;}if(state.stage===1){const i=state.guided,a=answer(i),v=app.querySelector('#guided-input')?.value.trim();if(a.phase===0){if(a.offset!==0){feedback('Line up the decimal points so the same place values are in the same columns.');return;}a.phase=i===0?1:3;}
else if(a.phase===1){if(v!=='0'){feedback('A trailing zero keeps 8.4 the same value. Try the digit 0.');return;}a.phase=2;}
else if(a.phase===2||a.phase===3){const expected=i===0?['5','7','0','1']:['5','8','4'];if(v!==expected[a.digits.length]){feedback((i===0?['Check the hundredths: 0 + 5.','Check the tenths: 4 + 3 tenths.','Check the ones: 8 + 2 = 10. Write the ones digit and carry 1 ten.','Use the carried 1 ten.']:['Check the hundredths: 0 + 5.','Check the tenths: 6 + 2.','Check the ones: 3 + 1.'])[a.digits.length]);return;}a.digits.push(v);a.phase=a.digits.length===expected.length?(i===0?4:5):3;if(a.phase===5)a.correct=true;}
else if(a.phase===4){if(v!=='aligned'){feedback('Look at the column containing both decimal points.');return;}a.phase=5;a.correct=true;}
else {if(i===0)state.guided=1;else {show(2);return;}}save();render();return;}
if(state.stage===2){const a=answer(state.practice);if(a.correct){if(state.practice<5)state.practice++;else {show(3);return;}save();render();return;}if(!a.value.trim()){feedback('Enter your answer before submitting.');return;}assess(state.practice);save();if(a.correct)render();else feedback(!a.aligned?'Look at where you placed the decimal points. Which digits are in the tenths column?':'Your decimal points line up. Check your addition and any carries, then try again.');return;}
if(!state.submitted){if(!answer(6).value.trim()||!answer(7).value.trim()||!state.reason?.trim()){feedback('Complete both calculations and your explanation before submitting.');return;}assess(6);assess(7);state.submitted=true;}else {state.reasonCorrect=app.querySelector('#reason-review').checked;state.reasonReviewed=true;state.reasonEarned=state.reasonEarned||state.reasonCorrect;if(state.reasonFirst===undefined)state.reasonFirst=state.reasonCorrect;}save();render();}
function show(n){state.stage=n;router.sync(ids[n]);save();render();}
function render(){app.innerHTML=`<header class="lesson-header lesson-header--compact rounding-header"><div class="lesson-header__inner"><h1 class="lesson-header__title">Adding decimal numbers</h1><div class="rounding-score"><div class="practice-progress-ring"><span>0</span></div></div></div></header><nav class="lesson-navigation lesson-navigation--stages" aria-label="Lesson sections"><div class="lesson-navigation__buttons">${ids.map((id,i)=>`<a class="lesson-navigation__button" href="#${id}" data-stage-number="${i+1}" ${i===state.stage?'aria-current="step"':''}>${labels[i]}</a>`).join('')}</div></nav><section class="lesson-section"><p class="lesson-eyebrow">${labels[state.stage]}</p>${[learn,guided,practice,check][state.stage]()}<p id="feedback" role="status"></p></section><footer class="lesson-controls"><div class="button-group"><button id="continue" class="button button--primary" type="button">Continue</button></div></footer>`;mountMoves();app.querySelector('#continue').onclick=next;app.querySelector('#retry-check')?.addEventListener('click',()=>{state.submitted=false;state.reasonReviewed=false;state.reason='';state.reasonCorrect=false;[6,7].forEach(i=>{const a=answer(i);a.value='';a.offset=1;a.correct=false;});save();render();});app.querySelectorAll('[data-answer]').forEach(el=>el.oninput=()=>{const a=answer(Number(el.dataset.answer));a.value=el.value;a.correct=false;save();});const reason=app.querySelector('#reason');if(reason)reason.oninput=()=>{state.reason=reason.value;save();};refreshScore();}
(async()=>{try{const saved=await store.getLessonProgress(slug);if(saved?.decimalState)state=saved.decimalState;}catch(e){console.warn('Unable to restore progress',e);}ids.forEach((id,i)=>router.register(id,()=>show(i)));if(!router.start())show(state.stage);})();
})();
